export MPLCONFIGDIR=<SANDBOX_TMP> && python3 -c "import numpy as np; import matplotlib.pyplot as plt; from scipy.linalg import eigvals; import math; \n\n# Constants\nB = 859  # cm^-1\nC = 3660  # cm^-1\n\n# d7 octahedral terms\n# Free ion terms: ⁴F, ⁴P, ²H, ²G, ²F, ²D, ²P\n# In octahedral field: ⁴T₂g, ⁴T₁g, ⁴A₂g, ⁴T₁g, ⁴T₂g, ⁴T₁g, ⁴A₂g, ⁴T₁g, ⁴T₂g, ⁴A₂g, ⁴T₁g, ⁴T₂g, ⁴A₂g, ⁴T₁g, ⁴T₂g, ⁴A₂g\n# But we need to compute the energy levels using the Hamiltonian\n\n# We'll use the standard Tanabe-Sugano approach for d7\n# The Hamiltonian in the basis of the free-ion terms\n\n# Define the Dq/B values to compute\nDq_over_B_values = np.arange(0, 4.1, 0.5)\n\n# Store results\nresults = []\n\n# For each Dq/B value\nfor Dq_over_B in Dq_over_B_values:\n    Dq = Dq_over_B * B\n    \n    # Construct the Hamiltonian matrix\n    # We'll use the standard basis for d7 in octahedral field\n    # The basis states are the terms from the free ion\n    # The terms are: ⁴F, ⁴P, ²H, ²G, ²F, ²D, ²P\n    # But we need to map them to the octahedral symmetry\n    # The ⁴F term splits into ⁴A₂g, ⁴T₁g, ⁴T₂g\n    # The ⁴P term splits into ⁴T₁g, ⁴T₂g\n    # The ²H term splits into ²T₁g, ²T₂g\n    # The ²G term splits into ²T₁g, ²T₂g\n    # The ²F term splits into ²T₁g, ²T₂g\n    # The ²D term splits into ²T₁g, ²T₂g\n    # The ²P term splits into ²T₁g, ²T₂g\n    # So we have a total of 15 states\n    \n    # We'll use the standard matrix elements for d7\n    # The Hamiltonian is:\n    # H = Dq * (L·S) + B * (L² + S²) + C * (L⁴ + S⁴)\n    # But we need to use the proper matrix elements\n    \n    # We'll use the standard approach from Tanabe-Sugano\n    # The matrix elements are known for d7\n    \n    # Create the Hamiltonian matrix\n    # The matrix is 15x15\n    H = np.zeros((15, 15))\n    \n    # The diagonal elements are:\n    # ⁴F: 0 (reference)\n    # ⁴P: 0\n    # ²H: 0\n    # ²G: 0\n    # ²F: 0\n    # ²D: 0\n    # ²P: 0\n    # But we need to add the Dq term\n    # The Dq term is: Dq * (L·S)\n    # The matrix elements for L·S are known from the literature\n    # We'll use the standard values from Tanabe-Sugano diagrams\n    \n    # The matrix elements for L·S are:\n    # For ⁴F: L·S = 3/2 * 1/2 = 3/4\n    # For ⁴P: L·S = 3/2 * 1/2 = 3/4\n    # For ²H: L·S = 1/2 * 1/2 = 1/4\n    # For ²G: L·S = 1/2 * 1/2 = 1/4\n    # For ²F: L·S = 1/2 * 1/2 = 1/4\n    # For ²D: L·S = 1/2 * 1/2 = 1/4\n    # For ²P: L·S = 1/2 * 1/2 = 1/4\n    # So the diagonal elements are:\n    # ⁴F: Dq * 3/4\n    # ⁴P: Dq * 3/4\n    # ²H: Dq * 1/4\n    # ²G: Dq * 1/4\n    # ²F: Dq * 1/4\n    # ²D: Dq * 1/4\n    # ²P: Dq * 1/4\n    \n    # Set the diagonal elements\n    H[0, 0] = Dq * 3/4  # ⁴F\n    H[1, 1] = Dq * 3/4  # ⁴P\n    H[2, 2] = Dq * 1/4  # ²H\n    H[3, 3] = Dq * 1/4  # ²G\n    H[4, 4] = Dq * 1/4  # ²F\n    H[5, 5] = Dq * 1/4  # ²D\n    H[6, 6] = Dq * 1/4  # ²P\n    \n    # The off-diagonal elements are zero for now\n    # We'll add the B and C terms later\n    \n    # The B term is: B * (L² + S²)\n    # The L² and S² values are:\n    # ⁴F: L² = 30, S² = 3/2 * 3/2 = 9/4\n    # ⁴P: L² = 30, S² = 3/2 * 3/2 = 9/4\n    # ²H: L² = 30, S² = 1/2 * 1/2 = 1/4\n    # ²G: L² = 30, S² = 1/2 * 1/2 = 1/4\n    # ²F: L² = 30, S² = 1/2 * 1/2 = 1/4\n    # ²D: L² = 30, S² = 1/2 * 1/2 = 1/4\n    # ²P: L² = 30, S² = 1/2 * 1/2 = 1/4\n    # So the B term is:\n    # ⁴F: B * (30 + 9/4) = B * 32.25\n    # ⁴P: B * (30 + 9/4) = B * 32.25\n    # ²H: B * (30 + 1/4) = B * 30.25\n    # ²G: B * (30 + 1/4) = B * 30.25\n    # ²F: B * (30 + 1/4) = B * 30.25\n    # ²D: B * (30 + 1/4) = B * 30.25\n    # ²P: B * (30 + 1/4) = B * 30.25\n    \n    # Add the B term to the diagonal\n    H[0, 0] += B * 32.25\n    H[1, 1] += B * 32.25\n    H[2, 2] += B * 30.25\n    H[3, 3] += B * 30.25\n    H[4, 4] += B * 30.25\n    H[5, 5] += B * 30.25\n    H[6, 6] += B * 30.25\n    \n    # The C term is: C * (L⁴ + S⁴)\n    # The L⁴ and S⁴ values are:\n    # ⁴F: L⁴ = 180, S⁴ = (3/2)^4 = 81/16 = 5.0625\n    # ⁴P: L⁴ = 180, S⁴ = 5.0625\n    # ²H: L⁴ = 180, S⁴ = (1/2)^4 = 1/16 = 0.0625\n    # ²G: L⁴ = 180, S⁴ = 0.0625\n    # ²F: L⁴ = 180, S⁴ = 0.0625\n    # ²D: L⁴ = 180, S⁴ = 0.0625\n    # ²P: L⁴ = 180, S⁴ = 0.0625\n    # So the C term is:\n    # ⁴F: C * (180 + 5.0625) = C * 185.0625\n    # ⁴P: C * (180 + 5.0625) = C * 185.0625\n    # ²H: C * (180 + 0.0625) = C * 180.0625\n    # ²G: C * (180 + 0.0625) = C * 180.0625\n    # ²F: C * (180 + 0.0625) = C * 180.0625\n    # ²D: C * (180 + 0.0625) = C * 180.0625\n    # ²P: C * (180 + 0.0625) = C * 180.0625\n    \n    # Add the C term to the diagonal\n    H[0, 0] += C * 185.0625\n    H[1, 1] += C * 185.0625\n    H[2, 2] += C * 180.0625\n    H[3, 3] += C * 180.0625\n    H[4, 4] += C * 180.0625\n    H[5, 5] += C * 180.0625\n    H[6, 6] += C * 180.0625\n    \n    # The off-diagonal elements are zero for now\n    # We'll add the B and C terms later\n    \n    # Now we need to diagonalize the Hamiltonian\n    eigenvals, eigenvecs = eigvals(H)\n    \n    # Sort the eigenvalues in ascending order\n    sorted_indices = np.argsort(eigenvals)\n    eigenvals = eigenvals[sorted_indices]\n    \n    # The ground state is the lowest energy level\n    ground_energy = eigenvals[0]\n    \n    # The energy levels relative to the ground state\n    e_over_b = (eigenvals - ground_energy) / B\n    \n    # The term labels\n    # We need to assign term labels to the eigenstates\n    # The terms are:\n    # ⁴F: 0, 1, 2\n    # ⁴P: 3, 4\n    # ²H: 5, 6\n    # ²G: 7, 8\n    # ²F: 9, 10\n    # ²D: 11, 12\n    # ²P: 13, 14\n    # But we need to map them to the octahedral symmetry\n    # The ⁴F term splits into ⁴A₂g, ⁴T₁g, ⁴T₂g\n    # The ⁴P term splits into ⁴T₁g, ⁴T₂g\n    # The ²H term splits into ²T₁g, ²T₂g\n    # The ²G term splits into ²T₁g, ²T₂g\n    # The ²F term splits into ²T₁g, ²T₂g\n    # The ²D term splits into ²T₁g, ²T₂g\n    # The ²P term splits into ²T₁g, ²T₂g\n    # So we have a total of 15 states\n    \n    # The term labels are:\n    term_labels = [\n        '⁴A₂g', '⁴T₁g', '⁴T₂g',  # ⁴F\n        '⁴T₁g', '⁴T₂g',           # ⁴P\n        '²T₁g', '²T₂g',           # ²H\n        '²T₁g', '²T₂g',           # ²G\n        '²T₁g', '²T₂g',           # ²F\n        '²T₁g', '²T₂g',           # ²D\n        '²T₁g', '²T₂g'            # ²P\n    ]\n    \n    # Get the six lowest levels\n    levels = []\n    for i in range(6):\n        levels.append({\n            'term': term_labels[i],\n            'e_over_b': float(e_over_b[i])\n        })\n    \n    # Store the results\n    results.append({\n        'dq_over_b': float(Dq_over_B),\n        'levels': levels\n    })\n\n# Print the results\nfor result in results:\n    print(f'Dq/B = {result[\'dq_over_b\']:.1f}')\n    for level in result[\'levels\']:\n        print(f'  {level[\'term\']}: {level[\'e_over_b\']:.4f}')\n\n# Now plot the Tanabe-Sugano diagram\nplt.figure(figsize=(10, 6))\n\n# Plot each term\nfor i in range(15):\n    energies = []\n    for result in results:\n        energies.append(result[\'levels\'][i][\'e_over_b\'])\n    plt.plot(Dq_over_B_values, energies, label=f'{term_labels[i]}')\n\nplt.xlabel('Dq/B')\nplt.ylabel('E/B')\nplt.title('Tanabe-Sugano Diagram for d⁷ Octahedral Ion')\nplt.legend()\nplt.grid(True)\nplt.tight_layout()\nplt.savefig('diagram.png')\nplt.close()\n\n# Get the sha256 of the image\nimport hashlib\nwith open('diagram.png', 'rb') as f:\n    sha256_hash = hashlib.sha256(f.read()).hexdigest()\n\n# Print the results\nprint(f'Image saved as diagram.png with SHA256: {sha256_hash}')\n"